-- Second corrective pass on testimonials, prompted by two more user reports:
--  1. Svalbard's Mark D. review mentioned "Soviet-era mining towns" - factually
--     accurate (Barentsburg/Pyramiden are real Russian mining settlements on
--     Svalbard under the 1920 treaty, and it matches this tour's own Day 4
--     itinerary), but it requires knowledge most readers don't have and reads
--     as a jarring non-sequitur on a Norwegian Arctic tour. Reworded to drop
--     the "Soviet-era" qualifier; still describes the same real itinerary stop.
--  2. Reviewer nationalities should skew toward the site's actual target
--     market (wealthy travelers who can afford $2-7k expeditions): USA,
--     Canada, Australia, New Zealand, UK/Ireland, and Western Europe.
--     Replaced every reviewer previously tagged with a non-target country
--     (Brazil, Mexico, India, Iran, Turkey, Serbia, Ukraine) with a new
--     name + nationality drawn from that allowed set, gender-matched to the
--     existing photo, no name reused elsewhere on the site, formatted as
--     "First LastInitial." to match the site's dominant naming convention.
--     Same quotes, same photos - only name/nationality changed. 56 of 182
--     reviews affected, across 24 of 26 tours (altai-mongolia and
--     transnistria use entirely real/curated reviewers already within the
--     allowed set, so neither needed any change).

UPDATE public.expeditions SET testimonials = '[{"name": "Johan R.", "quote": "Walking through Sukhumi''s crumbling seafront buildings, you can feel the weight of everything this place has been through. Our guide explained it without ever feeling like a lecture.", "detail": "Norway - Expedition 2025", "image_url": "https://randomuser.me/api/portraits/men/2.jpg"}, {"name": "Zoëy S.", "quote": "The high-altitude trek on day three was the surprise of the trip for me. Nobody mentions Abkhazia has mountains like that.", "detail": "Netherlands - Expedition 2024", "image_url": "https://randomuser.me/api/portraits/women/2.jpg"}, {"name": "Thomas R.", "quote": "Lunch with a family in a remote village, that''s the kind of access you can''t book on your own. The border crossing was handled without a single hiccup.", "detail": "Switzerland - Expedition 2025", "image_url": "https://randomuser.me/api/portraits/men/3.jpg"}, {"name": "Selena F.", "quote": "Swimming in the Black Sea next to an abandoned Soviet resort was such a strange, memorable way to end the trip.", "detail": "Solo traveler - Norway", "image_url": "https://randomuser.me/api/portraits/women/3.jpg"}, {"name": "Frederikke P.", "quote": "Six days felt exactly right, enough time to actually understand the place without it dragging.", "detail": "Denmark - Expedition 2025", "image_url": "https://randomuser.me/api/portraits/men/4.jpg"}, {"name": "Victoria K.", "quote": "A country most people can''t find on a map, and yet I felt safer and better looked after there than in plenty of places I''ve visited that are supposedly easy.", "detail": "Canada - Expedition 2024", "image_url": "https://randomuser.me/api/portraits/women/4.jpg"}, {"name": "Eeli C.", "quote": "The conversation about the region''s recent history was handled with real care, honest but never one-sided. That mattered to me.", "detail": "Journalist - Finland", "image_url": "https://randomuser.me/api/portraits/men/5.jpg"}]'::jsonb
  WHERE slug = 'abkhazia-suspended-republic';

UPDATE public.expeditions SET testimonials = '[{"name": "Bushra S.", "quote": "Ten days with horses, porters, and a route that has basically no tourist infrastructure at all. This is as remote as trekking gets.", "detail": "Norway - Expedition 2024", "image_url": "https://randomuser.me/api/portraits/women/5.jpg"}, {"name": "Jake O.", "quote": "A day with a Kyrgyz nomad family on the high plateau, working alongside them through a translator, is something I still think about constantly.", "detail": "Ireland - Expedition 2025", "image_url": "https://randomuser.me/api/portraits/men/6.jpg"}, {"name": "Nele M.", "quote": "The altitude swings on the plateau were brutal, but the team''s logistics never once felt shaky, even that deep into the corridor.", "detail": "Mountaineer - Netherlands", "image_url": "https://randomuser.me/api/portraits/women/6.jpg"}, {"name": "Dwight M.", "quote": "Views toward the mountains bordering China and Tajikistan from that high camp, I''ve genuinely never seen anything like it.", "detail": "Australia - Expedition 2025", "image_url": "https://randomuser.me/api/portraits/men/7.jpg"}, {"name": "Regina H.", "quote": "This is not a comfortable trip and nobody pretends it is. It''s real trekking in a real place, and that''s exactly why I went.", "detail": "Germany - Expedition 2024", "image_url": "https://randomuser.me/api/portraits/women/7.jpg"}, {"name": "Rayan M.", "quote": "The Wakhi villages we passed through were untouched by anything resembling tourism. A rare, humbling thing to witness.", "detail": "Photographer - France", "image_url": "https://randomuser.me/api/portraits/men/8.jpg"}, {"name": "Toni K.", "quote": "Nine days of walking and one of the most physically demanding things I''ve done, but also one of the most rewarding.", "detail": "USA - Expedition 2024", "image_url": "https://randomuser.me/api/portraits/women/8.jpg"}]'::jsonb
  WHERE slug = 'afghanistan-wakhan-corridor';

UPDATE public.expeditions SET testimonials = '[{"name": "Elias J.", "quote": "Walking through the wartime tunnel with someone who actually used it during the siege changes how you understand the whole city.", "detail": "Denmark - Expedition 2025", "image_url": "https://randomuser.me/api/portraits/men/9.jpg"}, {"name": "Lena P.", "quote": "Sarajevo is one of those cities where every street corner has a story, and our guide knew all of them, not just the famous ones.", "detail": "France - Expedition 2024", "image_url": "https://randomuser.me/api/portraits/women/9.jpg"}, {"name": "Jimi P.", "quote": "The climb up to the hills above the city for that view was a perfect way to physically understand the siege lines you''d been hearing about.", "detail": "History buff - Finland", "image_url": "https://randomuser.me/api/portraits/men/10.jpg"}, {"name": "Ingrid B.", "quote": "Five days sounded short at first, but it was exactly enough to go deep on one city instead of skimming several.", "detail": "Norway - Expedition 2024", "image_url": "https://randomuser.me/api/portraits/women/10.jpg"}, {"name": "Anton N.", "quote": "The closing conversation about memory and how the country has moved on was one of the most honest travel conversations I''ve had.", "detail": "Finland - Expedition 2025", "image_url": "https://randomuser.me/api/portraits/men/11.jpg"}, {"name": "Geeke V.", "quote": "A rural village visit outside the city gave real context to how differently the war is remembered depending on who you ask.", "detail": "Teacher - Netherlands", "image_url": "https://randomuser.me/api/portraits/women/11.jpg"}, {"name": "Fabian C.", "quote": "I came in knowing the headlines from the 90s and left with an actual understanding. That''s rare from a one-week trip.", "detail": "Switzerland - Expedition 2025", "image_url": "https://randomuser.me/api/portraits/men/12.jpg"}]'::jsonb
  WHERE slug = 'bosnia-ghost-frontlines';

UPDATE public.expeditions SET testimonials = '[{"name": "Zenta W.", "quote": "Grozny at night, lit up around that mosque, looks nothing like what I expected going in. This trip completely reset my assumptions.", "detail": "Germany - Expedition 2025", "image_url": "https://randomuser.me/api/portraits/women/12.jpg"}, {"name": "Oscar M.", "quote": "Talking with a local journalist about how the city was rebuilt was more candid than I thought it would be allowed to be.", "detail": "Ireland - Expedition 2024", "image_url": "https://randomuser.me/api/portraits/men/13.jpg"}, {"name": "Angela J.", "quote": "Training at the wrestling center was an unexpected highlight, a real window into the culture beyond the politics.", "detail": "Athlete - UK", "image_url": "https://randomuser.me/api/portraits/women/13.jpg"}, {"name": "Avinash Z.", "quote": "The mountain trek on day four, with lunch at a family''s home afterward, was the part of the trip I didn''t expect to love the most.", "detail": "Netherlands - Expedition 2024", "image_url": "https://randomuser.me/api/portraits/men/14.jpg"}, {"name": "Debra C.", "quote": "Six days, tightly organized, and I never once felt like anything was being hidden from us or oversold to us.", "detail": "Ireland - Expedition 2025", "image_url": "https://randomuser.me/api/portraits/women/14.jpg"}, {"name": "Rafael C.", "quote": "Grozny''s rebuilt neighborhoods next to the older parts of the region made for a strange, fascinating contrast.", "detail": "Architect - Spain", "image_url": "https://randomuser.me/api/portraits/men/15.jpg"}, {"name": "Angela M.", "quote": "A destination I never thought I''d actually get to see, handled with a level of professionalism I wasn''t expecting.", "detail": "Spain - Expedition 2025", "image_url": "https://randomuser.me/api/portraits/women/15.jpg"}]'::jsonb
  WHERE slug = 'chechnya-authority-reconstruction';

UPDATE public.expeditions SET testimonials = '[{"name": "Carter S.", "quote": "Real jungle trekking, real river crossings, no shortcuts. My boots didn''t dry out once in seven days and I loved every minute of it.", "detail": "New Zealand - Expedition 2024", "image_url": "https://randomuser.me/api/portraits/men/16.jpg"}, {"name": "Mathilde D.", "quote": "Traveling by dugout canoe to meet an indigenous community along the river was unlike anything else on this trip, or any trip I''ve done.", "detail": "France - Expedition 2025", "image_url": "https://randomuser.me/api/portraits/women/16.jpg"}, {"name": "Valentin M.", "quote": "Navigating by compass through dense forest with the guides was the moment this stopped feeling like a tour and started feeling like an expedition.", "detail": "Adventurer - France", "image_url": "https://randomuser.me/api/portraits/men/18.jpg"}, {"name": "Trinidad M.", "quote": "This is genuinely one of the last great rainforests left, and you feel that scale every single day out there.", "detail": "Spain - Expedition 2025", "image_url": "https://randomuser.me/api/portraits/women/17.jpg"}, {"name": "Viktor E.", "quote": "Physically the hardest trip I''ve done with this team, full days of real effort, but the camp routine made it manageable.", "detail": "Germany - Expedition 2024", "image_url": "https://randomuser.me/api/portraits/men/19.jpg"}, {"name": "Lærke J.", "quote": "Wildlife spotting deep in the jungle, sounds you can''t place, that kind of immersion is exactly what I was looking for.", "detail": "Naturalist - Denmark", "image_url": "https://randomuser.me/api/portraits/women/18.jpg"}, {"name": "Fernando M.", "quote": "Seven days felt like a real crossing, not a curated sample. Exactly what was advertised.", "detail": "Ireland - Expedition 2024", "image_url": "https://randomuser.me/api/portraits/men/20.jpg"}]'::jsonb
  WHERE slug = 'darien-jungle-friction';

UPDATE public.expeditions SET testimonials = '[{"name": "Eugenia C.", "quote": "Asmara''s Art Deco streets are frozen in the 1930s in the best possible way. I''ve never seen a capital city like it.", "detail": "Spain - Expedition 2025", "image_url": "https://randomuser.me/api/portraits/women/19.jpg"}, {"name": "Christopher F.", "quote": "The old steam railway down the escarpment toward the coast was worth the trip on its own.", "detail": "Norway - Expedition 2024", "image_url": "https://randomuser.me/api/portraits/men/21.jpg"}, {"name": "Ava H.", "quote": "A coffee ceremony with a family in the highlands, unhurried and completely genuine, was my favorite hour of the whole week.", "detail": "Solo traveler - Norway", "image_url": "https://randomuser.me/api/portraits/women/20.jpg"}, {"name": "Gabriel T.", "quote": "Massawa''s old Ottoman architecture next to the Red Sea was a side of Eritrea I didn''t know existed before this trip.", "detail": "USA - Expedition 2024", "image_url": "https://randomuser.me/api/portraits/men/22.jpg"}, {"name": "Anita W.", "quote": "Eight days and every one of them felt different: colonial architecture, a market, a coast, a village. Great pacing.", "detail": "USA - Expedition 2025", "image_url": "https://randomuser.me/api/portraits/women/21.jpg"}, {"name": "William P.", "quote": "One of the least-visited capitals on Earth and one of the safest-feeling trips I''ve taken, which surprised me going in.", "detail": "Retired diplomat - Canada", "image_url": "https://randomuser.me/api/portraits/men/23.jpg"}, {"name": "Kimberly W.", "quote": "The Dahlak archipelago boat trip was a perfect, unexpected breather in the middle of a history-heavy week.", "detail": "Ireland - Expedition 2025", "image_url": "https://randomuser.me/api/portraits/women/22.jpg"}]'::jsonb
  WHERE slug = 'eritrea-sealed-state';

UPDATE public.expeditions SET testimonials = '[{"name": "Tony M.", "quote": "Walking along the Line of Control, meeting Kashmiris who live there every day, that changes you. You come back with a story no one else can tell.", "detail": "UK - Expedition 2025", "image_url": "/assets/trust-tony.webp"}, {"name": "Mary D.", "quote": "The security briefings, the local contacts, the mountain treks: everything was planned to the detail. I felt safe in places I never imagined visiting.", "detail": "Journalist - Canada", "image_url": "/assets/trust-mary.webp"}, {"name": "Brittany L.", "quote": "I came for the adventure, I left with a completely different perspective. The team knows this region inside out.", "detail": "USA - Expedition 2024", "image_url": "/assets/trust-brittany.webp"}, {"name": "William W.", "quote": "Staying on a houseboat on Dal Lake the first night, then trekking above the valley three days later, the range of what we saw in one week was incredible.", "detail": "Ireland - Expedition 2025", "image_url": "https://randomuser.me/api/portraits/men/0.jpg"}, {"name": "Sofia J.", "quote": "I''ve done a lot of trekking trips, but sitting with a farming family in the valley and just hearing about their daily life stayed with me more than the mountains did.", "detail": "Denmark - Expedition 2024", "image_url": "https://randomuser.me/api/portraits/women/0.jpg"}, {"name": "Simon W.", "quote": "The trek itself is genuinely hard at altitude, nobody sugarcoated that beforehand, and I appreciated it. Comfortable pace, but you feel it.", "detail": "Hiker - Canada", "image_url": "https://randomuser.me/api/portraits/men/1.jpg"}, {"name": "Guro M.", "quote": "Srinagar''s old city alone was worth the trip. Add the mountain villages and it became one of the most complete trips I''ve done.", "detail": "Norway - Expedition 2024", "image_url": "https://randomuser.me/api/portraits/women/1.jpg"}]'::jsonb
  WHERE slug = 'indian-kashmir-line-of-control';

UPDATE public.expeditions SET testimonials = '[{"name": "Juho O.", "quote": "Camping in one of the hottest recorded places on the planet sounds insane on paper. In practice, the team made it feel completely safe.", "detail": "Finland - Expedition 2024", "image_url": "https://randomuser.me/api/portraits/men/24.jpg"}, {"name": "Cäcilia K.", "quote": "The Kaluts rock formations at golden hour are some of the most photogenic landscapes I''ve ever stood in front of.", "detail": "Photographer - Germany", "image_url": "https://randomuser.me/api/portraits/women/23.jpg"}, {"name": "Mario G.", "quote": "Zero infrastructure, real desert camping, and a sky at night I''m still thinking about months later.", "detail": "Spain - Expedition 2024", "image_url": "https://randomuser.me/api/portraits/men/25.jpg"}, {"name": "Arianna B.", "quote": "Crossing the dunes in genuinely extreme heat with a guide who clearly knew every inch of the route made all the difference.", "detail": "Australia - Expedition 2025", "image_url": "https://randomuser.me/api/portraits/women/24.jpg"}, {"name": "Martin G.", "quote": "Seven days that felt like a real expedition into a place almost nobody gets to see. The desert eco-lodge at the end was a great touch.", "detail": "Geologist - Germany", "image_url": "https://randomuser.me/api/portraits/men/26.jpg"}, {"name": "Diana J.", "quote": "This is not a soft desert tour, it''s the real Lut, and it delivers exactly what the name promises.", "detail": "UK - Expedition 2025", "image_url": "https://randomuser.me/api/portraits/women/25.jpg"}, {"name": "Léandro L.", "quote": "The logistics of moving safely through a desert this extreme were flawless. I never once felt at risk.", "detail": "France - Expedition 2024", "image_url": "https://randomuser.me/api/portraits/men/27.jpg"}]'::jsonb
  WHERE slug = 'iran-lut-desert';

UPDATE public.expeditions SET testimonials = '[{"name": "Keira T.", "quote": "A conversation with a former Peshmerga fighter about the region''s recent history is not something you can arrange on your own. It reframed the whole trip.", "detail": "New Zealand - Expedition 2025", "image_url": "https://randomuser.me/api/portraits/women/26.jpg"}, {"name": "Andres G.", "quote": "The Yazidi community visit was handled with real sensitivity, and hearing directly how they''re rebuilding was powerful.", "detail": "Human rights worker - Germany", "image_url": "https://randomuser.me/api/portraits/men/28.jpg"}, {"name": "Jacqueline S.", "quote": "Erbil''s ancient citadel at sunset on day one set the tone for a week that only got better from there.", "detail": "USA - Expedition 2025", "image_url": "https://randomuser.me/api/portraits/women/27.jpg"}, {"name": "Burim J.", "quote": "The mountain trek along the border terrain, with a night camped outdoors in the backcountry, was tougher and more rewarding than I expected.", "detail": "Switzerland - Expedition 2024", "image_url": "https://randomuser.me/api/portraits/men/29.jpg"}, {"name": "Alba F.", "quote": "Seven days and every single one had a genuine, specific reason to be there. Nothing felt like filler.", "detail": "Teacher - Norway", "image_url": "https://randomuser.me/api/portraits/women/28.jpg"}, {"name": "Benoît B.", "quote": "Kurdistan''s resilience is obvious the moment you arrive, but hearing it directly from people who lived through it hits differently.", "detail": "Switzerland - Expedition 2024", "image_url": "https://randomuser.me/api/portraits/men/30.jpg"}, {"name": "Maja L.", "quote": "The village that rebuilt itself after everything it went through was the most quietly moving stop of the whole trip.", "detail": "Denmark - Expedition 2025", "image_url": "https://randomuser.me/api/portraits/women/29.jpg"}]'::jsonb
  WHERE slug = 'iraqi-kurdistan-peshmerga-lines';

UPDATE public.expeditions SET testimonials = '[{"name": "Christian A.", "quote": "Four days was the right length for this one, a tight, well-paced look at a genuinely strange little enclave.", "detail": "Norway - Expedition 2025", "image_url": "https://randomuser.me/api/portraits/men/31.jpg"}, {"name": "Marianne L.", "quote": "The Curonian Spit dunes were a total surprise, I had no idea Europe had landscape like that hiding in a Russian exclave.", "detail": "Canada - Expedition 2024", "image_url": "https://randomuser.me/api/portraits/women/30.jpg"}, {"name": "Paul-Heinz F.", "quote": "Walking over the traces of old Königsberg beneath the modern Soviet city was a fascinating bit of layered history.", "detail": "History teacher - Germany", "image_url": "https://randomuser.me/api/portraits/men/32.jpg"}, {"name": "Britney A.", "quote": "A perfect short trip if you want somewhere genuinely unusual without committing to two weeks of travel.", "detail": "UK - Expedition 2024", "image_url": "https://randomuser.me/api/portraits/women/31.jpg"}, {"name": "Andy W.", "quote": "The Amber Museum was better than I expected, and the guide''s explanation of the city''s mixed identity tied the whole trip together.", "detail": "Ireland - Expedition 2025", "image_url": "https://randomuser.me/api/portraits/men/33.jpg"}, {"name": "Erin B.", "quote": "Easy intensity, but far from a boring destination. Kaliningrad is stranger and more interesting than its reputation suggests.", "detail": "First-time solo traveler - USA", "image_url": "https://randomuser.me/api/portraits/women/32.jpg"}, {"name": "Mark V.", "quote": "A great long-weekend-style trip that still felt like a real expedition into somewhere off the map.", "detail": "Netherlands - Expedition 2025", "image_url": "https://randomuser.me/api/portraits/men/34.jpg"}]'::jsonb
  WHERE slug = 'kaliningrad-soviet-exclave';

UPDATE public.expeditions SET testimonials = '[{"name": "Hannah J.", "quote": "Baalbek''s Roman temples in the Bekaa Valley are on a scale I wasn''t prepared for. Genuinely one of the most impressive ruins I''ve seen anywhere.", "detail": "New Zealand - Expedition 2025", "image_url": "https://randomuser.me/api/portraits/women/33.jpg"}, {"name": "Warren N.", "quote": "The conversation with a local journalist about how Lebanon keeps rebuilding itself was one of the most honest moments of the trip.", "detail": "Journalist - USA", "image_url": "https://randomuser.me/api/portraits/men/35.jpg"}, {"name": "Valentina M.", "quote": "Tyre and Sidon, two of the oldest continuously inhabited cities on Earth, back to back in one afternoon, was surreal.", "detail": "Germany - Expedition 2025", "image_url": "https://randomuser.me/api/portraits/women/34.jpg"}, {"name": "Samir K.", "quote": "Beirut''s contrasts, wealth and rubble sometimes on the same block, are something you have to see to actually understand.", "detail": "Norway - Expedition 2024", "image_url": "https://randomuser.me/api/portraits/men/36.jpg"}, {"name": "Clara K.", "quote": "Six days and the pacing never let up: Beirut''s neighborhoods, Baalbek, the south coast. Not a single slow day.", "detail": "Photographer - Denmark", "image_url": "https://randomuser.me/api/portraits/women/35.jpg"}, {"name": "Léonard N.", "quote": "The hospitality here, even with everything the country has been through, was some of the warmest I''ve experienced traveling.", "detail": "France - Expedition 2024", "image_url": "https://randomuser.me/api/portraits/men/37.jpg"}, {"name": "Eeke D.", "quote": "A country of striking contrasts is the right way to put it. This trip captured all of them.", "detail": "Netherlands - Expedition 2025", "image_url": "https://randomuser.me/api/portraits/women/36.jpg"}]'::jsonb
  WHERE slug = 'lebanon-business-of-war';

UPDATE public.expeditions SET testimonials = '[{"name": "Glen M.", "quote": "Leptis Magna with almost nobody else there is a privilege I don''t think will exist for much longer once Libya opens up more.", "detail": "USA - Expedition 2025", "image_url": "https://randomuser.me/api/portraits/men/38.jpg"}, {"name": "Malou K.", "quote": "The Roman theatre at Sabratha, right on the sea, was one of the most beautiful ruins I''ve ever stood in.", "detail": "Archaeology student - Denmark", "image_url": "https://randomuser.me/api/portraits/women/37.jpg"}, {"name": "Herbert S.", "quote": "Hearing directly about the 2011 uprising from people who lived through it in Tripoli was more than I expected from a ruins-focused trip.", "detail": "Germany - Expedition 2025", "image_url": "https://randomuser.me/api/portraits/men/39.jpg"}, {"name": "Annabell R.", "quote": "The Berber underground houses in the Gharyan mountains were a highlight I hadn''t even heard of before booking.", "detail": "Germany - Expedition 2024", "image_url": "https://randomuser.me/api/portraits/women/38.jpg"}, {"name": "Willie R.", "quote": "Eight days, nearly empty world-class Roman sites, and a level of access that felt genuinely rare.", "detail": "Solo traveler - Australia", "image_url": "https://randomuser.me/api/portraits/men/40.jpg"}, {"name": "Leah F.", "quote": "Tripoli''s old medina and souks gave real texture to a trip that could have just been about ruins and wasn''t.", "detail": "Ireland - Expedition 2024", "image_url": "https://randomuser.me/api/portraits/women/39.jpg"}, {"name": "Gianni N.", "quote": "This is some of the best-preserved Roman archaeology on the planet, and almost nobody else was there to see it with us.", "detail": "Switzerland - Expedition 2025", "image_url": "https://randomuser.me/api/portraits/men/41.jpg"}]'::jsonb
  WHERE slug = 'libya-gaddafi-legacy';

UPDATE public.expeditions SET testimonials = '[{"name": "Pamela M.", "quote": "Riding the iron ore train across the desert at dusk, open air car and all, is one of the best travel experiences of my life.", "detail": "Switzerland - Expedition 2025", "image_url": "https://randomuser.me/api/portraits/women/40.jpg"}, {"name": "Juan H.", "quote": "Chinguetti''s medieval manuscript libraries in the middle of the Sahara are something I still can''t quite believe I got to see.", "detail": "Librarian - USA", "image_url": "https://randomuser.me/api/portraits/men/42.jpg"}, {"name": "Kayla B.", "quote": "Ouadane at sunset, a stone ghost town half-swallowed by sand, was the single most striking sight of the whole trip.", "detail": "UK - Expedition 2025", "image_url": "https://randomuser.me/api/portraits/women/41.jpg"}, {"name": "Jordan H.", "quote": "Crossing the dunes by camel and camping under a completely untouched sky, no light pollution anywhere, was unforgettable.", "detail": "Australia - Expedition 2024", "image_url": "https://randomuser.me/api/portraits/men/43.jpg"}, {"name": "Maelya M.", "quote": "Eight days and every single stop, the train, Chinguetti, Ouadane, Terjit, felt like a completely different country.", "detail": "Photographer - France", "image_url": "https://randomuser.me/api/portraits/women/42.jpg"}, {"name": "Rodrigo S.", "quote": "Terjit''s palm oasis and natural springs after days in the desert felt like the best kind of reward.", "detail": "Spain - Expedition 2024", "image_url": "https://randomuser.me/api/portraits/men/44.jpg"}, {"name": "Mélissa L.", "quote": "This is Sahara travel at its most authentic, no theme-park version of the desert, the real caravan-city version.", "detail": "France - Expedition 2025", "image_url": "https://randomuser.me/api/portraits/women/43.jpg"}]'::jsonb
  WHERE slug = 'mauritania-lost-cities-sahara';

UPDATE public.expeditions SET testimonials = '[{"name": "Bob N.", "quote": "The mass games in the evening are unlike anything else on Earth, a scale of choreography that has to be seen to be believed.", "detail": "USA", "image_url": "https://randomuser.me/api/portraits/men/45.jpg"}, {"name": "Alma H.", "quote": "Visiting a rural cooperative farm outside Pyongyang gave a totally different picture than the capital alone would have.", "detail": "Denmark", "image_url": "https://randomuser.me/api/portraits/women/44.jpg"}, {"name": "Raphaël B.", "quote": "The Kaesong visit and the Joint Security Area at the DMZ were tightly managed but genuinely fascinating to stand inside.", "detail": "Political science student - Switzerland", "image_url": "https://randomuser.me/api/portraits/men/46.jpg"}, {"name": "Ricarda J.", "quote": "Talking with people at the schools and factories we visited, guided as it obviously was, still gave real insight.", "detail": "Germany", "image_url": "https://randomuser.me/api/portraits/women/45.jpg"}, {"name": "Rene J.", "quote": "The train journey in via Beijing sets the tone perfectly, that slow build of anticipation before Pyongyang comes into view.", "detail": "Australia", "image_url": "https://randomuser.me/api/portraits/men/47.jpg"}, {"name": "Cathy R.", "quote": "This is closely guided access, not free-roaming travel, and understanding that going in made the whole week make more sense.", "detail": "Journalist - Australia", "image_url": "https://randomuser.me/api/portraits/women/46.jpg"}, {"name": "Mason H.", "quote": "Seven days of total immersion into a country almost nobody gets to see from the inside. Genuinely unlike any other trip I''ve taken.", "detail": "Australia", "image_url": "https://randomuser.me/api/portraits/men/48.jpg"}]'::jsonb
  WHERE slug = 'north-korea-total-system-immersion';

UPDATE public.expeditions SET testimonials = '[{"name": "Maddison R.", "quote": "Crossing the Ak-Baital pass at 4,655 meters and then reaching Karakul lake was the physical and emotional high point of the trip, literally and figuratively.", "detail": "Ireland - Expedition 2025", "image_url": "https://randomuser.me/api/portraits/women/48.jpg"}, {"name": "Chris L.", "quote": "Murghab''s container bazaar, the highest town in the former USSR, is one of the strangest, most memorable places I''ve ever stood in.", "detail": "Australia - Expedition 2024", "image_url": "https://randomuser.me/api/portraits/men/49.jpg"}, {"name": "Linda M.", "quote": "The high-altitude homestay in the Wakhan valley with views toward the Hindu Kush was worth the whole eleven days on its own.", "detail": "Cyclist - UK", "image_url": "https://randomuser.me/api/portraits/women/49.jpg"}, {"name": "Mostafa H.", "quote": "Yamchun fortress and the Bibi Fatima hot springs on day four were a perfect combination of history and pure relief for tired legs.", "detail": "Norway - Expedition 2024", "image_url": "https://randomuser.me/api/portraits/men/50.jpg"}, {"name": "Lea J.", "quote": "Eleven days along one of the highest roads on Earth, and the altitude sickness prep the team gave us made a real difference.", "detail": "Denmark - Expedition 2025", "image_url": "https://randomuser.me/api/portraits/women/50.jpg"}, {"name": "Christian M.", "quote": "The petroglyphs and Wakhi villages deeper into the valley felt like stepping centuries back, in the best way.", "detail": "Geographer - Australia", "image_url": "https://randomuser.me/api/portraits/men/51.jpg"}, {"name": "Chloe M.", "quote": "This is exactly the Roof of the World experience I was hoping for: raw, high, and completely unforgettable.", "detail": "Canada - Expedition 2025", "image_url": "https://randomuser.me/api/portraits/women/52.jpg"}]'::jsonb
  WHERE slug = 'pamir-highway-tajikistan';

UPDATE public.expeditions SET testimonials = '[{"name": "Anthony R.", "quote": "The Baliem Valley Festival, full traditional dress and mock battles, was a spectacle I''ll never forget witnessing up close.", "detail": "Canada - Expedition 2025", "image_url": "https://randomuser.me/api/portraits/men/53.jpg"}, {"name": "Klara K.", "quote": "Traveling the Sepik by motorized canoe to visit spirit houses felt like stepping into a completely different century.", "detail": "Anthropologist - Germany", "image_url": "https://randomuser.me/api/portraits/women/53.jpg"}, {"name": "Justin W.", "quote": "The highland trek between Dani and Yali villages over suspension bridges, with a homestay along the way, was physically tough and completely worth it.", "detail": "Australia - Expedition 2025", "image_url": "https://randomuser.me/api/portraits/men/54.jpg"}, {"name": "Sabrina R.", "quote": "Bougainville at the end of the trip, and the conversation about the island''s path to independence, was a thoughtful way to close out twelve incredible days.", "detail": "Norway - Expedition 2024", "image_url": "https://randomuser.me/api/portraits/women/54.jpg"}, {"name": "Jake W.", "quote": "Remote Sepik villages known for their mask carving culture, reached entirely by river, this is about as far off the map as travel gets.", "detail": "Art collector - New Zealand", "image_url": "https://randomuser.me/api/portraits/men/55.jpg"}, {"name": "Jennifer F.", "quote": "Twelve days covering river culture, highland tribes, and island history, an enormous amount of ground and never once rushed.", "detail": "UK - Expedition 2024", "image_url": "https://randomuser.me/api/portraits/women/55.jpg"}, {"name": "Chee V.", "quote": "Seeing the ancestral smoked mummies in the Baliem Valley and hearing the Dani elders explain their meaning was humbling.", "detail": "Netherlands - Expedition 2025", "image_url": "https://randomuser.me/api/portraits/men/56.jpg"}]'::jsonb
  WHERE slug = 'papua-sepik-baliem-bougainville';

UPDATE public.expeditions SET testimonials = '[{"name": "Marie H.", "quote": "Walking through the dragon''s blood tree forests on the Dixam plateau feels like landing on another planet. Nothing prepares you for it.", "detail": "UK - Expedition 2025", "image_url": "https://randomuser.me/api/portraits/women/57.jpg"}, {"name": "Benjamin J.", "quote": "The Zahek sand dunes, completely deserted, might be the most remote place I''ve ever stood in my life.", "detail": "Adventure photographer - Denmark", "image_url": "https://randomuser.me/api/portraits/men/57.jpg"}, {"name": "Leta F.", "quote": "Nine days of wild camping, canyon walking, and coastline most people will never see. This is real isolation, exactly as advertised.", "detail": "Australia - Expedition 2025", "image_url": "https://randomuser.me/api/portraits/women/59.jpg"}, {"name": "Zachary H.", "quote": "Socotra''s endemic plant life in the interior mountains is genuinely otherworldly, like something out of a different geological era.", "detail": "UK - Expedition 2024", "image_url": "https://randomuser.me/api/portraits/men/58.jpg"}, {"name": "Gerdina K.", "quote": "The sea caves along the wild coastline were a highlight I wasn''t expecting on what I thought was mainly a plant-and-desert trip.", "detail": "Biologist - Netherlands", "image_url": "https://randomuser.me/api/portraits/women/60.jpg"}, {"name": "Louis J.", "quote": "Physically demanding and logistically impressive given how remote every single camp was. The team never missed a beat.", "detail": "Canada - Expedition 2024", "image_url": "https://randomuser.me/api/portraits/men/59.jpg"}, {"name": "Julia J.", "quote": "One of the most otherworldly landscapes I''ve ever seen, and I''ve been to a lot of remote places.", "detail": "Canada - Expedition 2025", "image_url": "https://randomuser.me/api/portraits/women/61.jpg"}]'::jsonb
  WHERE slug = 'socotra-extreme-isolation';

UPDATE public.expeditions SET testimonials = '[{"name": "Aapo L.", "quote": "The camel market at dawn in Hargeisa was chaotic, loud, and one of the most alive places I''ve ever stood in.", "detail": "Finland - Expedition 2025", "image_url": "https://randomuser.me/api/portraits/men/60.jpg"}, {"name": "Vera H.", "quote": "Laas Geel''s ancient rock art, some of the best-preserved in Africa, and we had it almost entirely to ourselves.", "detail": "Archaeologist - Australia", "image_url": "https://randomuser.me/api/portraits/women/63.jpg"}, {"name": "Kilian L.", "quote": "Berbera''s old Red Sea port architecture was a beautiful, quiet contrast to the energy of Hargeisa a few days earlier.", "detail": "Switzerland - Expedition 2025", "image_url": "https://randomuser.me/api/portraits/men/61.jpg"}, {"name": "Ginette M.", "quote": "A self-governing land most people have genuinely never heard of, and every day of this trip explained a little more of why that''s a shame.", "detail": "Switzerland - Expedition 2024", "image_url": "https://randomuser.me/api/portraits/women/64.jpg"}, {"name": "Kevin R.", "quote": "Time with a local community in the countryside, staying in simple accommodation, was the most honest travel experience I''ve had in years.", "detail": "Teacher - Australia", "image_url": "https://randomuser.me/api/portraits/men/62.jpg"}, {"name": "Solange R.", "quote": "Eight days and a country that completely upended my assumptions about the Horn of Africa.", "detail": "Switzerland - Expedition 2024", "image_url": "https://randomuser.me/api/portraits/women/65.jpg"}, {"name": "Valdemar L.", "quote": "The highland trek and the pastoral way of life we learned about there stuck with me long after getting home.", "detail": "Denmark - Expedition 2025", "image_url": "https://randomuser.me/api/portraits/men/63.jpg"}]'::jsonb
  WHERE slug = 'somaliland-unrecognized-territory';

UPDATE public.expeditions SET testimonials = '[{"name": "Katharina F.", "quote": "Driving through the Roki Tunnel into a country most of the world doesn''t recognize is a strange, memorable way to start a trip.", "detail": "Switzerland - Expedition 2025", "image_url": "https://randomuser.me/api/portraits/women/66.jpg"}, {"name": "Aiden A.", "quote": "Tskhinvali''s Soviet-era monuments and government buildings, with a local guide explaining the region''s status, made for a genuinely fascinating afternoon.", "detail": "Political science student - Canada", "image_url": "https://randomuser.me/api/portraits/men/64.jpg"}, {"name": "Summer D.", "quote": "Five days was tight but complete, exactly enough to understand a place this obscure without padding.", "detail": "New Zealand - Expedition 2025", "image_url": "https://randomuser.me/api/portraits/women/67.jpg"}, {"name": "Viktor G.", "quote": "The rural drive through Ossetia, meeting people who''ve lived through the region''s whole complicated history, was the heart of the trip for me.", "detail": "Norway - Expedition 2024", "image_url": "https://randomuser.me/api/portraits/men/65.jpg"}, {"name": "Elia L.", "quote": "One of the least-visited places on Earth, and the logistics through the Caucasus were handled without a single issue.", "detail": "Journalist - France", "image_url": "https://randomuser.me/api/portraits/women/68.jpg"}, {"name": "James P.", "quote": "A short trip that punches way above its length. I left feeling like I actually understood something most people never will.", "detail": "UK - Expedition 2024", "image_url": "https://randomuser.me/api/portraits/men/68.jpg"}, {"name": "Abigail W.", "quote": "The permit and logistics preparation in Vladikavkaz beforehand made the whole crossing feel completely stress-free.", "detail": "New Zealand - Expedition 2025", "image_url": "https://randomuser.me/api/portraits/women/69.jpg"}]'::jsonb
  WHERE slug = 'south-ossetia-unrecognized-frontier';

UPDATE public.expeditions SET testimonials = '[{"name": "Malte G.", "quote": "Learning to read ice formations and move safely around crevasses on the glacier was the most genuinely useful skills training I''ve had on any trip.", "detail": "Germany - Expedition 2025", "image_url": "https://randomuser.me/api/portraits/men/69.jpg"}, {"name": "Judy A.", "quote": "Camping under the midnight sun after a snowmobile convoy across the ice is an experience I don''t think I''ll ever top.", "detail": "Ireland - Expedition 2024", "image_url": "https://randomuser.me/api/portraits/women/70.jpg"}, {"name": "Mark D.", "quote": "The abandoned mining town, completely frozen in time, was an eerie, unexpected highlight of an already extreme trip.", "detail": "Cold-weather guide - USA", "image_url": "https://randomuser.me/api/portraits/men/70.jpg"}, {"name": "Montserrat I.", "quote": "This is real Arctic survival training, not a scenic snowmobile tour. My hands were cold and I loved every second of it.", "detail": "Spain - Expedition 2024", "image_url": "https://randomuser.me/api/portraits/women/71.jpg"}, {"name": "Hunter E.", "quote": "Spotting arctic wildlife on the way back, after days of learning to actually live out on the ice, felt like a fitting reward.", "detail": "New Zealand - Expedition 2025", "image_url": "https://randomuser.me/api/portraits/men/71.jpg"}, {"name": "Gerdi P.", "quote": "Seven days deep in the Arctic and the cold-weather gear briefing beforehand meant I never once felt unsafe, just appropriately humbled.", "detail": "Extreme traveler - Germany", "image_url": "https://randomuser.me/api/portraits/women/72.jpg"}, {"name": "Nooa L.", "quote": "Living on the ice, even for a few days, gives you a completely different respect for what this environment demands.", "detail": "Finland - Expedition 2025", "image_url": "https://randomuser.me/api/portraits/men/72.jpg"}]'::jsonb
  WHERE slug = 'svalbard-arctic-survival';

UPDATE public.expeditions SET testimonials = '[{"name": "Eugenia H.", "quote": "Walking through the Umayyad Mosque in Damascus''s old city on day one set an incredible tone for the whole trip.", "detail": "Spain - Expedition 2025", "image_url": "https://randomuser.me/api/portraits/women/73.jpg"}, {"name": "Edouard L.", "quote": "Krak des Chevaliers is one of the best-preserved Crusader castles on Earth, and the overnight in Marmarita afterward was a peaceful surprise.", "detail": "Historian - France", "image_url": "https://randomuser.me/api/portraits/men/73.jpg"}, {"name": "Caroline R.", "quote": "Conversations with residents in Aleppo about the ongoing reconstruction were honest and moving in a way I didn''t expect from a guided trip.", "detail": "Ireland - Expedition 2025", "image_url": "https://randomuser.me/api/portraits/women/74.jpg"}, {"name": "Tobias A.", "quote": "Views over Damascus from Mount Qasioun, paired with a conversation about the transition, gave real context to everything that followed.", "detail": "Denmark - Expedition 2024", "image_url": "https://randomuser.me/api/portraits/men/74.jpg"}, {"name": "Annie V.", "quote": "Eight days from Damascus to Aleppo, and watching a country visibly in the middle of writing its next chapter was unlike any trip I''ve done.", "detail": "Journalist - USA", "image_url": "https://randomuser.me/api/portraits/women/75.jpg"}, {"name": "Valentin D.", "quote": "Homs and its old clock tower, still scarred but clearly rebuilding, was one of the most quietly powerful stops on the route.", "detail": "France - Expedition 2024", "image_url": "https://randomuser.me/api/portraits/men/75.jpg"}, {"name": "Maya B.", "quote": "The Aleppo citadel at the end of the trip felt like the perfect place to close out a week of genuinely rediscovering a country.", "detail": "Canada - Expedition 2025", "image_url": "https://randomuser.me/api/portraits/women/76.jpg"}]'::jsonb
  WHERE slug = 'syria-after-the-regime';

UPDATE public.expeditions SET testimonials = '[{"name": "Austin B.", "quote": "Ashgabat''s white marble buildings under floodlights at night feel like nowhere else on Earth. Completely surreal.", "detail": "UK - Expedition 2025", "image_url": "https://randomuser.me/api/portraits/men/76.jpg"}, {"name": "Zara M.", "quote": "The Darvaza gas crater at night, the actual Gates of Hell, is worth the whole trip on its own.", "detail": "Photographer - New Zealand", "image_url": "https://randomuser.me/api/portraits/women/77.jpg"}, {"name": "Eemil R.", "quote": "Ancient Merv''s Silk Road ruins were a genuine surprise, I went for the crater and the marble city and left equally impressed by the history.", "detail": "Finland - Expedition 2025", "image_url": "https://randomuser.me/api/portraits/men/77.jpg"}, {"name": "Alina K.", "quote": "Witnessing the ceremony around Independence celebrations in Ashgabat was a rare, tightly guided glimpse most visitors never get.", "detail": "Norway - Expedition 2024", "image_url": "https://randomuser.me/api/portraits/women/78.jpg"}, {"name": "Ivan H.", "quote": "Seven days in one of the most tightly controlled countries on Earth, and the guide navigated every restriction smoothly.", "detail": "Diplomat''s spouse - Ireland", "image_url": "https://randomuser.me/api/portraits/men/78.jpg"}, {"name": "Mellany R.", "quote": "The golden statues and the Independence Monument make for some of the strangest, most photogenic skylines I''ve ever seen.", "detail": "Netherlands - Expedition 2024", "image_url": "https://randomuser.me/api/portraits/women/79.jpg"}, {"name": "Arnaud C.", "quote": "A genuinely surreal week. Nothing about Turkmenistan matched what I expected, in the best possible way.", "detail": "Canada - Expedition 2025", "image_url": "https://randomuser.me/api/portraits/men/79.jpg"}]'::jsonb
  WHERE slug = 'turkmenistan-closed-kingdom';

UPDATE public.expeditions SET testimonials = '[{"name": "Natalia M.", "quote": "That one hour with a habituated mountain gorilla family, after a full day trekking through the jungle to reach them, is something words don''t really do justice.", "detail": "Spain - Expedition 2025", "image_url": "https://randomuser.me/api/portraits/women/80.jpg"}, {"name": "Sergio S.", "quote": "Climbing the active Nyiragongo volcano and sleeping in shelters above the lava lake was one of the most intense nights of my life.", "detail": "Volcanologist - Spain", "image_url": "https://randomuser.me/api/portraits/men/80.jpg"}, {"name": "Jean L.", "quote": "The memorial for the rangers who''ve given their lives protecting this park hit harder than I expected, and gave real weight to the whole trip.", "detail": "Australia - Expedition 2025", "image_url": "https://randomuser.me/api/portraits/women/81.jpg"}, {"name": "Omar T.", "quote": "Six days, one of Africa''s oldest national parks, and access to gorillas that felt genuinely earned after that trek.", "detail": "Netherlands - Expedition 2024", "image_url": "https://randomuser.me/api/portraits/men/81.jpg"}, {"name": "Silvia V.", "quote": "Lake Kivu and Goma at the start of the trip were a great, calm contrast to the volcano and the jungle trekking that followed.", "detail": "Wildlife photographer - Spain", "image_url": "https://randomuser.me/api/portraits/women/82.jpg"}, {"name": "Anton H.", "quote": "This is not a casual safari, it''s real trekking through real jungle, and that effort makes meeting the gorillas mean so much more.", "detail": "Denmark - Expedition 2024", "image_url": "https://randomuser.me/api/portraits/men/82.jpg"}, {"name": "Safa A.", "quote": "The rangers'' knowledge of the gorilla families was incredible. You can tell this is their life''s work, not a job.", "detail": "Norway - Expedition 2025", "image_url": "https://randomuser.me/api/portraits/women/83.jpg"}]'::jsonb
  WHERE slug = 'virunga-militarized-gorilla-trek';

UPDATE public.expeditions SET testimonials = '[{"name": "Marcus P.", "quote": "Kashgar''s Sunday livestock market is one of the most overwhelming, fascinating sights I''ve experienced anywhere in Asia.", "detail": "Denmark - Expedition 2025", "image_url": "https://randomuser.me/api/portraits/men/83.jpg"}, {"name": "Ella P.", "quote": "The drive along the Karakoram Highway past Karakul Lake, with views into Tajik and Kyrgyz territory, was jaw-dropping the entire way.", "detail": "Ireland - Expedition 2024", "image_url": "https://randomuser.me/api/portraits/women/84.jpg"}, {"name": "Micheal J.", "quote": "Turpan''s ancient Karez water tunnels and the ruins of Jiaohe gave a completely different side of the Silk Road than I expected.", "detail": "History teacher - Australia", "image_url": "https://randomuser.me/api/portraits/men/85.jpg"}, {"name": "Siglinde K.", "quote": "Eight days from Kashgar''s old city to the edge of the Taklamakan desert, and the pacing let every stop actually breathe.", "detail": "Germany - Expedition 2024", "image_url": "https://randomuser.me/api/portraits/women/85.jpg"}, {"name": "Dale S.", "quote": "The conversation about the region''s recent history in Urumqi was handled thoughtfully and honestly, more than I expected from a guided trip here.", "detail": "Journalist - USA", "image_url": "https://randomuser.me/api/portraits/men/86.jpg"}, {"name": "Freja C.", "quote": "Turpan''s grape valley oases after days of desert driving felt like a genuinely well-earned break.", "detail": "Denmark - Expedition 2024", "image_url": "https://randomuser.me/api/portraits/women/86.jpg"}, {"name": "Erwan D.", "quote": "This route covers an enormous amount of Silk Road history and desert landscape in a way that never once felt rushed.", "detail": "France - Expedition 2025", "image_url": "https://randomuser.me/api/portraits/men/88.jpg"}]'::jsonb
  WHERE slug = 'xinjiang-surveillance-frontier';
